/* ===== YOU DO ===== */
function stageYouDo(){
  var tierNote=S.tier==='support'?'Use the sentence starters and fill in one box at a time.':S.tier==='push'?'Write a full paragraph (5–7 sentences), 2+ quotes from EACH character, and add what the comparison SHOWS.':'Write a comparison paragraph: at least one similarity, one difference, each proved with a quote.';
  var starters='<div class="frames"><b>Sentence starters:</b> '+YOUDO.starters.map(function(s){return esc(s);}).join(' · ')+'</div>';
  var pushBox=S.tier==='push'?'<label class="fld" for="yWhat">What does the comparison SHOW about each character? (push)</label><textarea class="in" id="yWhat" placeholder="Comparing them shows that…"></textarea>':'';
  return '<div class="slide"><div class="slide-head red"><span class="gem">7</span><h2>You Do — Your turn</h2></div>'+
  '<div class="slide-body"><span class="stage-pill">Independent practice</span>'+
  '<h4 style="margin:0 0 8px;color:var(--navy)">'+esc(YOUDO.title)+'</h4>'+
  '<p>'+esc(tierNote)+'</p>'+(S.tier==='support'?starters:'')+
  '<label class="fld" for="y_same">One thing they have in COMMON (with a quote)</label><textarea class="in" id="y_same" placeholder="Both Miss Honey and Trunchbull…"></textarea>'+
  '<label class="fld" for="y_diff">One DIFFERENCE (with a quote from each)</label><textarea class="in" id="y_diff" placeholder="However, Miss Honey… whereas Trunchbull…"></textarea>'+
  pushBox+cardTray()+
  '<div class="btn-row"><span class="sp"></span><button class="btn" id="ydNext">Next: Exit Ticket &#8594;</button></div>'+
  '<img class="crest" src="'+LOGO+'" alt=""></div></div>';
}
function cardTray(){
  var html='<div class="tray">';
  if(S.tier==='core') html+=psCard(CARDS.support)+psCard(CARDS.push);
  else { html+=psCard(S.tier==='support'?CARDS.support:CARDS.push); html+=psCard(S.tier==='support'?CARDS.push:CARDS.support); }
  html+='</div>';
  return '<div style="margin-top:14px"><div class="stage-pill">Help cards — use if stuck or for a challenge</div>'+html+'</div>';
}
function psCard(c){var cls=c===CARDS.support?'support':'push';return '<div class="pscard '+cls+'"><div class="lab">'+esc(c.title)+'</div><div style="font-size:.78rem;color:var(--ink-soft);margin-bottom:4px">'+esc(c.move)+'</div><ul>'+c.items.map(function(i){return '<li>'+esc(i)+'</li>';}).join('')+'</ul></div>';}

/* ===== EXIT TICKET ===== */
function stageExit(){
  return '<div class="slide"><div class="slide-head"><span class="gem">8</span><h2>Exit Ticket</h2></div>'+
  '<div class="slide-body"><span class="stage-pill">Show what you learned</span>'+
  mcqBlock(EXIT,'ex-opt')+
  '<button class="btn" id="exCheck">Check my answers</button><div class="fb" id="exFb"></div>'+
  '<div class="btn-row" id="exNextRow" style="display:none"><span class="sp"></span><button class="btn" id="exNext">Finish &#10003;</button></div>'+
  '<img class="crest" src="'+LOGO+'" alt=""></div></div>';
}

/* ===== DONE ===== */
function stageDone(){
  var sc=S.stageScores;
  return '<div class="slide"><div class="slide-head teal"><span class="gem">&#9733;</span><h2>Lesson complete</h2></div>'+
  '<div class="slide-body"><span class="stage-pill">Well done, '+esc(S.name)+'!</span>'+
  '<p>You worked through the whole lesson — Do Now to Exit Ticket — comparing characters with evidence. Your teacher can see your results.</p>'+
  '<div class="dash-grid" style="grid-template-columns:repeat(3,1fr)">'+
    stat((sc.donow!=null?(sc.donow?'✓':'✗'):'–'),'Do Now')+
    stat((sc.affirm!=null?sc.affirm+'/6':'–'),'Affirmative Check')+
    stat((sc.exit!=null?sc.exit+'/2':'–'),'Exit Ticket')+'</div>'+
  '<p class="muted" style="font-size:.85rem">Remember the GEM exit routine: gather your belongings, leave quietly and calmly, go straight to your next class.</p>'+
  '<div class="btn-row"><button class="btn ghost" onclick="restartStudent()">Back to start</button></div>'+
  '<img class="crest" src="'+LOGO+'" alt=""></div></div>';
}
function restartStudent(){S.studentId=null;S.placed=false;S.stageIndex=0;S.stageScores={};S.preScore=null;S.lowTestFlag=false;go('');}

/* ===== WIRING ===== */
function selWire(){
  document.querySelectorAll('.choice').forEach(function(btn){
    btn.addEventListener('click',function(){
      var qi=btn.getAttribute('data-qi');
      var cls=['pre-opt','ret-opt','ex-opt','dn-opt','we-opt','conn-opt'].filter(function(c){return btn.classList.contains(c);})[0]||'';
      var scope = (qi!=null) ? ('.'+cls+'[data-qi="'+qi+'"]') : ('.'+cls);
      document.querySelectorAll(scope).forEach(function(b){b.classList.remove('sel');});
      btn.classList.add('sel');
    });
  });
  document.querySelectorAll('.aff-row .pill').forEach(function(p){
    p.addEventListener('click',function(){var qi=p.getAttribute('data-qi');document.querySelectorAll('.pill[data-qi="'+qi+'"]').forEach(function(b){b.classList.remove('chosen');});p.classList.add('chosen');});
  });
}
function wireStage(stage){
  selWire();
  var adv=function(){advance();};

  if(stage==='pretest'){
    el('preCheck').addEventListener('click',function(){
      var r=gradeMCQ(PRETEST,'pre-opt'),f=el('preFb');
      if(r.answered<PRETEST.length){f.className='fb show no';f.textContent='Answer all 5, then check.';return;}
      S.preScore=r.correct;
      S.lowTestFlag = r.correct<=1;
      S.tier=placePath(S.ngrt,r.correct);
      var basis = S.ngrt!=null ? ('reading age '+S.ngrt) : ('pre-test '+r.correct+'/5');
      var recMap={support:'Support path',core:'Core path',push:'Push path'};
      var extra = S.lowTestFlag && S.ngrt!=null ? ' Your reading age sets your path, but your pre-test was low — your teacher has been flagged to check in.' : '';
      el('recBox').innerHTML='<div class="rec '+S.tier+'"><h3>'+recMap[S.tier]+' &nbsp;<span class="chip '+S.tier+'">'+S.tier+'</span></h3><p style="margin:4px 0 0">Based on '+esc(basis)+'. Pre-test: '+r.correct+'/5.'+extra+'</p></div>';
      f.className='fb show ok';f.innerHTML='<b>Thanks!</b> Here’s your path.';
      el('preNextRow').style.display='flex'; S.placed=true; saveStudent();
    });
    el('preNext').addEventListener('click',adv);
  }

  if(stage==='retrieval'){
    el('retCheck').addEventListener('click',function(){
      var r=gradeMCQ(RETRIEVAL.items,'ret-opt'),f=el('retFb');
      if(r.answered<RETRIEVAL.items.length){f.className='fb show no';f.textContent='Answer all, then check.';return;}
      f.className='fb show ok';f.innerHTML='<b>'+r.correct+' / '+r.total+'.</b> PLACE was for settings; today we compare <b>characters</b> with a new strategy.';
      el('retNextRow').style.display='flex'; saveStudent();
    });
    el('retNext').addEventListener('click',adv);
  }

  if(stage==='donow'){
    el('dnCheck').addEventListener('click',function(){
      var sel=document.querySelector('.dn-opt.sel'),f=el('dnFb');
      if(!sel){f.className='fb show no';f.textContent='Pick an answer first.';return;}
      document.querySelectorAll('.dn-opt').forEach(function(b){var oi=parseInt(b.getAttribute('data-oi'),10);if(oi===DONOW.answer)b.classList.add('correct');else if(b.classList.contains('sel'))b.classList.add('wrong');});
      var ok=parseInt(sel.getAttribute('data-oi'),10)===DONOW.answer;
      S.stageScores.donow=ok?1:0;
      f.className='fb show ok';f.innerHTML='<b>'+(ok?'Correct!':'Good try.')+'</b> '+DONOW.feedback;
      el('dnNextRow').style.display='flex'; saveStudent();
    });
    el('dnNext').addEventListener('click',adv);
  }

  if(stage==='keywords'){ el('kwNext').addEventListener('click',adv); }
  if(stage==='outcome'){ el('loNext').addEventListener('click',adv); }
  if(stage==='ido'){ el('idoNext').addEventListener('click',adv); }

  if(stage==='wedo'){
    el('weCheck').addEventListener('click',function(){
      var sel=document.querySelector('.we-opt.sel'),f=el('weFb');
      if(!sel){f.className='fb show no';f.textContent='Pick an answer first.';return;}
      var ok=sel.getAttribute('data-ok')==='1';
      document.querySelectorAll('.we-opt').forEach(function(b){if(b.getAttribute('data-ok')==='1')b.classList.add('correct');else if(b.classList.contains('sel'))b.classList.add('wrong');});
      var picked=WEDO.options[parseInt(sel.getAttribute('data-oi'),10)];
      f.className='fb show ok';f.innerHTML='<b>'+(ok?'Yes!':'Look again.')+'</b> '+picked.why;
      el('weNextRow').style.display='flex'; saveStudent();
    });
    el('weNext').addEventListener('click',adv);
  }

  if(stage==='affirm'){
    el('affCheck').addEventListener('click',function(){
      var rows=document.querySelectorAll('.aff-row'),ansd=0,cor=0;
      rows.forEach(function(r){var qi=r.getAttribute('data-qi');var ch=document.querySelector('.pill[data-qi="'+qi+'"].chosen');r.classList.remove('row-correct','row-wrong');if(ch){ansd++;var right=ch.getAttribute('data-val')===r.getAttribute('data-ans');if(right){cor++;r.classList.add('row-correct');}else r.classList.add('row-wrong');}});
      var csel=document.querySelector('.conn-opt.sel');
      var f=el('affFb');
      if(ansd<rows.length||!csel){f.className='fb show no';f.textContent='Answer every sentence and the connective, then check.';return;}
      document.querySelectorAll('.conn-opt').forEach(function(b){var oi=parseInt(b.getAttribute('data-oi'),10);if(oi===AFFIRM.connective.answer)b.classList.add('correct');else if(b.classList.contains('sel'))b.classList.add('wrong');});
      if(parseInt(csel.getAttribute('data-oi'),10)===AFFIRM.connective.answer) cor++;
      S.stageScores.affirm=cor; S.needsSupport = cor<4 ? true : S.needsSupport;
      f.className='fb show ok';f.innerHTML='<b>'+cor+' / 6.</b> '+AFFIRM.connective.why;
      el('affNextRow').style.display='flex'; saveStudent();
    });
    el('affNext').addEventListener('click',adv);
  }

  if(stage==='youdo'){
    el('ydNext').addEventListener('click',function(){
      if(S.tier==='push'&&val('yWhat').length>3)S.usedPush=true;
      saveStudent({written:{same:val('y_same'),diff:val('y_diff'),what:val('yWhat')}}); advance();
    });
  }

  if(stage==='exit'){
    el('exCheck').addEventListener('click',function(){
      var r=gradeMCQ(EXIT,'ex-opt'),f=el('exFb');
      if(r.answered<EXIT.length){f.className='fb show no';f.textContent='Answer both, then check.';return;}
      S.stageScores.exit=r.correct;
      f.className='fb show ok';f.innerHTML='<b>'+r.correct+' / 2.</b> Correct answers are shown in green.';
      el('exNextRow').style.display='flex'; saveStudent();
    });
    el('exNext').addEventListener('click',adv);
  }
}
function val(id){var e=el(id);return e?(e.value||'').trim():'';}
function advance(){
  var target=Math.min(S.stageIndex+1,STAGES.length-1);
  if(!gateAllows(target)){ S.waiting=true; saveStudent(); window.scrollTo({top:0,behavior:'smooth'}); render(); return; }
  S.stageIndex=target; S.waiting=false; saveStudent(); window.scrollTo({top:0,behavior:'smooth'}); render();
}

/* ---------------- boot ---------------- */
(function(){var bl=el('brandLogo');if(bl)bl.src=LOGO;})();
initFirebase().then(function(){ render(); });
